CREATE TABLE IF NOT EXISTS contacts (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', kind TEXT NOT NULL DEFAULT 'lead', source TEXT NOT NULL DEFAULT '', stage TEXT NOT NULL DEFAULT 'New', next_follow_up TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deals (id INTEGER PRIMARY KEY, contact_id INTEGER NOT NULL REFERENCES contacts(id), title TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'Lead', closing_date TEXT NOT NULL DEFAULT '', checklist TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, actor TEXT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER NOT NULL, detail TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS contacts_follow_up ON contacts(next_follow_up);
CREATE INDEX IF NOT EXISTS deals_stage ON deals(stage);
